export type Decision = { prompt: string; choices: string[]; answer: number; rationale: string };
export type DeepDay = {
  mission: string;
  caseTitle: string;
  caseContext: string;
  walkthrough: string[];
  decision: Decision;
  recall: { prompt: string; answer: string }[];
  protocol: string[];
  reflection: string;
};

const day = (mission: string, caseTitle: string, caseContext: string, walkthrough: string[], decision: Decision, recall: DeepDay['recall'], protocol: string[], reflection: string): DeepDay => ({ mission, caseTitle, caseContext, walkthrough, decision, recall, protocol, reflection });

export const academyDepth: Record<number, DeepDay> = {
  1: day('Separate the problem, the data, the learning signal, and the deployed prediction.', 'Triage assistant for a support queue', 'A team wants to route incoming support tickets before a human reads them. It has historical tickets labelled billing, access, and technical.', ['Frame the output: one of three categories, so this is classification—not text generation.', 'Define features available at prediction time: ticket text and product area; exclude the human resolution label.', 'Hold out recent tickets to check whether the model transfers to new writing styles.', 'Deploy a prediction with a confidence threshold so uncertain tickets stay with a human.'], { prompt: 'Which change is the safest first improvement when accuracy looks excellent in testing but weak after launch?', choices: ['Add more layers immediately', 'Check whether future or post-resolution data leaked into training', 'Increase the temperature', 'Replace labels with embeddings'], answer: 1, rationale: 'A dramatic offline/online gap often points to leakage or a mismatch between training and production data. More capacity can hide the issue rather than repair it.' }, [{ prompt: 'What makes a label different from a feature?', answer: 'The label is what the model is asked to predict; features are inputs available when that prediction is made.' }, { prompt: 'Why is a validation set not the final score?', answer: 'It guides modelling choices. A final untouched test set is needed for an honest estimate after those choices.' }, { prompt: 'When is an AI system not necessarily an ML system?', answer: 'A rule-based routing system can automate decisions without learning its rules from examples.' }], ['Write the ticket-routing input schema.', 'Mark each field as feature, label, identifier, or leakage risk.', 'Describe one low-confidence handoff rule.', 'Explain the system in 45 seconds without using jargon.'], 'Before choosing an algorithm, ask: what decision is being made, what evidence exists at that moment, and what happens when the system is unsure.'),
  2: day('Choose metrics that reflect the cost of a wrong decision, not the metric that looks best in a slide.', 'Fraud review with a limited analyst team', 'A payment team can only manually review 300 transactions each day. Missing fraud is costly, but sending too many normal users to review causes friction.', ['Draw the confusion matrix around the positive class: fraud.', 'Recall measures caught fraud among all real fraud; precision measures how often a flagged transaction truly is fraud.', 'Pick a threshold based on analyst capacity and business cost, not an arbitrary 0.5.', 'Monitor drift because fraud tactics and normal purchase behaviour both change.'], { prompt: 'The team wants fewer innocent customers held for review while retaining useful alerts. What should it inspect first?', choices: ['Precision at the chosen review volume', 'Training accuracy', 'Number of model parameters', 'The model file size'], answer: 0, rationale: 'Precision answers how many alerts are actually fraud. Evaluate it at the operational threshold or top-k volume the review team can handle.' }, [{ prompt: 'Why can 99% accuracy be useless in fraud detection?', answer: 'With rare fraud, predicting “not fraud” for every transaction can score highly while catching none of the cases that matter.' }, { prompt: 'What is a threshold?', answer: 'A rule converting a model score into an action, such as sending only scores above 0.82 to review.' }, { prompt: 'What is calibration?', answer: 'A calibrated 0.8 score should correspond to roughly an 80% chance of the event across similar cases.' }], ['Calculate precision and recall from a four-cell confusion matrix.', 'Choose a review threshold for a 300-case daily capacity.', 'Write the operational cost of a false positive and false negative.', 'State one fairness check before launch.'], 'A metric is a contract with the real decision. Name the error you can least afford before you optimise it.'),
  3: day('Explain why an LLM can recognise meaning without treating it as a database of exact documents.', 'Semantic search for policy questions', 'Employees ask “Can I expense a home-office chair?” but policy language says “ergonomic equipment reimbursement.” Keyword search misses the connection.', ['Tokenisation breaks text into units the model can process; it is not the same as words.', 'Embeddings map related meanings near one another in a vector space.', 'Attention weighs relevant token relationships inside the active context.', 'The context window limits the input currently considered; it does not guarantee correctness.'], { prompt: 'What is the most appropriate first layer for semantic matching of employee questions to policy passages?', choices: ['Exact string comparison only', 'Embedding-based retrieval', 'A larger temperature value', 'Retraining the model after every question'], answer: 1, rationale: 'Embeddings enable meaning-based similarity. Generation comes after relevant evidence is found.' }, [{ prompt: 'What does a context window limit?', answer: 'The amount of input and generated text a model can consider in one request.' }, { prompt: 'Why are embeddings useful before generation?', answer: 'They make it practical to retrieve semantically related passages from a large collection.' }, { prompt: 'What does attention contribute conceptually?', answer: 'It lets a transformer weight relationships between parts of the current sequence based on relevance.' }], ['Compare a token, an embedding, and a parameter in one table.', 'Sketch question → embedding → nearest policy chunk → answer.', 'Find one case where a keyword search may still be better.', 'Explain why a long context does not remove the need to retrieve carefully.'], 'Meaning similarity helps find evidence; it does not prove that the evidence is current, authorised, or sufficient.'),
  4: day('Write instructions that make an AI output inspectable, bounded, and testable.', 'Release-note assistant', 'A product manager needs release notes from a list of merged pull requests. The assistant must not invent shipped features and must use a supplied tone.', ['Separate trusted instructions from untrusted PR text and user-provided context.', 'Specify audience, source material, output shape, exclusions, and a factuality rule.', 'Use a small example only if it clarifies the desired structure.', 'Evaluate outputs against a checklist: unsupported claims, omitted changes, tone, and format.'], { prompt: 'Which prompt addition best reduces invented release notes?', choices: ['“Be creative and comprehensive.”', '“If a claim is not supported by the supplied PR summary, write ‘not evidenced’ and omit it.”', '“Use a high temperature.”', '“Write as much as possible.”'], answer: 1, rationale: 'A grounding and abstention rule defines the evidence boundary. Style requests or sampling settings do not establish truth.' }, [{ prompt: 'What is the difference between a system instruction and retrieved context?', answer: 'A system instruction sets trusted behaviour; retrieved context is evidence to use, not authority to override safety or policy.' }, { prompt: 'When is few-shot prompting helpful?', answer: 'When examples clarify a stable output pattern that prose instructions might leave ambiguous.' }, { prompt: 'Why test prompts with adversarial inputs?', answer: 'Because untrusted text may try to redirect the model or reveal that instructions are underspecified.' }], ['Draft a five-line release-note prompt with an output schema.', 'Add one explicit refusal or abstention condition.', 'Create a two-item evaluation checklist.', 'Rewrite the prompt for a non-technical customer audience.'], 'A good prompt is a miniature specification: inputs, constraints, output, and a way to judge failure.'),
  5: day('Design RAG as an evidence pipeline with retrieval quality and access control as first-class concerns.', 'Permission-aware policy assistant', 'A financial-services assistant answers from internal policy documents that change weekly. Different departments may see different documents.', ['Ingest and version documents; split them into chunks that preserve enough local meaning.', 'Attach metadata such as source, update time, department, and access policy before indexing.', 'Filter by permissions before similarity search; then retrieve, rerank, and cite the strongest passages.', 'Validate that the answer is supported. If evidence is weak, answer with a limitation instead of guessing.'], { prompt: 'What should occur before semantic retrieval in a system with departmental permissions?', choices: ['Increase the context window', 'Filter candidate documents by the requester’s authorisation', 'Fine-tune the model on every document', 'Remove metadata for privacy'], answer: 1, rationale: 'Access control belongs in retrieval. Once confidential text is retrieved, a later wording instruction cannot reliably undo the exposure.' }, [{ prompt: 'Why is chunk size a trade-off?', answer: 'Large chunks preserve context but can dilute matching and consume context; small chunks retrieve precisely but may lose necessary surrounding conditions.' }, { prompt: 'What does reranking add?', answer: 'It applies a more expensive relevance judgment to a small retrieved candidate set to improve the final evidence.' }, { prompt: 'Why is RAG not a hallucination guarantee?', answer: 'The model can still misread, overgeneralise, or answer beyond weak or conflicting retrieved evidence.' }], ['Draw the secure RAG pipeline from ingestion to cited answer.', 'Choose chunk boundaries for a policy with exceptions.', 'Write an “insufficient evidence” response.', 'List one prompt-injection defence for retrieved text.'], 'Retrieval decides what the model is allowed to see. Generation should make that evidence visible, not replace it.'),
  6: day('Treat AI features as software systems: instrument them, bound their tools, and make failures observable.', 'Order-status agent with a shipping tool', 'An agent can look up an order and draft a customer response. A malformed user message asks it to cancel an order and ignore its normal approval process.', ['Define which tools exist, what each accepts, and which actions require confirmation.', 'Keep tool results structured so the model does not parse ambiguous prose.', 'Log request ID, retrieved sources, tool calls, latency, cost, errors, and user-visible outcome.', 'Use monitoring to detect rising tool failures, unsupported answers, and cost regressions.'], { prompt: 'Which control most directly prevents a chat message from silently cancelling an order?', choices: ['Give the model more context', 'Require an explicit confirmed action with server-side authorisation', 'Raise temperature', 'Hide the tool name from logs'], answer: 1, rationale: 'A consequential action needs deterministic backend authorisation and confirmation. A model instruction is not an access-control system.' }, [{ prompt: 'What is observability?', answer: 'The ability to infer system state from useful outputs such as logs, metrics, traces, and structured events.' }, { prompt: 'Why separate tool planning from execution?', answer: 'It makes validation and approval possible before an external side effect occurs.' }, { prompt: 'What should an AI trace link together?', answer: 'The request, retrieval, prompt version, model response, tools, latency, cost, and final outcome.' }], ['Define a safe order-lookup tool schema.', 'Mark which action needs confirmation.', 'Write three alert conditions for this agent.', 'Explain the difference between a log and a trace.'], 'An agent is not an autonomous permission boundary. Its tools must be designed like any other production API.'),
  7: day('Use a timed AI practice run to diagnose decisions under pressure, not to produce a vanity score.', 'AI section rehearsal', 'You have 20 AI questions and roughly half the total MCQ time. Several stems are long and two choices sound plausible.', ['Read the final sentence first so you know what decision is requested.', 'Underline constraints: freshness, cost, security, latency, evidence, or model-weight changes.', 'Eliminate choices that solve only part of the stated problem.', 'Flag genuine trade-offs, then return with remaining time instead of guessing from panic.'], { prompt: 'A question asks for current policy answers without retraining. Which contrast should you recognise immediately?', choices: ['RAG versus fine-tuning', 'Precision versus recall', 'TCP versus UDP', 'Stack versus queue'], answer: 0, rationale: 'The “current documents without weight updates” cue points to retrieval-augmented generation, while fine-tuning changes model behaviour through training.' }, [{ prompt: 'What makes an option a close distractor?', answer: 'It is partly correct but fails an explicit constraint in the stem.' }, { prompt: 'When should you flag a question?', answer: 'When two answers remain plausible after constraint matching and additional time could resolve the trade-off.' }, { prompt: 'What should you record after a mock?', answer: 'The missed concept, the ignored constraint, and the faster recognition rule for next time.' }], ['Run 10 timed AI scenarios.', 'For every miss, label the constraint you ignored.', 'Write a one-sentence rule for the top two errors.', 'Retest only those rules tomorrow.'], 'Speed comes from recognising decision patterns, not from skimming the sentence that changes the answer.'),
  8: day('Model relationships and dependencies before writing SQL.', 'Subscription billing schema', 'A SaaS company tracks customers, plans, subscriptions, invoices, and payments. It needs history without duplicate customer facts.', ['Identify entities and the facts that belong to each entity.', 'Choose stable primary keys and represent relationships with foreign keys.', 'State candidate keys and uniqueness constraints before normalising.', 'Check whether a fact depends on the whole key and only the key.'], { prompt: 'Where should the customer’s current plan price be stored if prices change over time?', choices: ['Repeated in every payment row only', 'In a plan/version record referenced by the subscription', 'As free text in the customer name', 'Only in application memory'], answer: 1, rationale: 'A versioned plan record preserves historical meaning while subscriptions reference the applicable plan. Repeating price creates update anomalies.' }, [{ prompt: 'What is the purpose of a foreign key?', answer: 'It enforces that a referenced relationship points to an existing valid record.' }, { prompt: 'Why is normalisation useful?', answer: 'It reduces update, insertion, and deletion anomalies by placing each fact in an appropriate relation.' }, { prompt: 'What does cardinality describe?', answer: 'How many records of one entity can be related to records of another entity.' }], ['Sketch five tables and their keys.', 'Mark one-to-many relationships.', 'Find one update anomaly in an unnormalised sheet.', 'State one deliberate reason to denormalise later.'], 'Good SQL begins with a truthful model. Query cleverness cannot compensate for a relationship the schema never captured.'),
  9: day('Read a query as a transformation of rows, especially when NULL and joins change which rows survive.', 'Dormant-customer report', 'Marketing wants every customer, including customers with no orders in the last 90 days. An analyst accidentally filters orders in a WHERE clause after a LEFT JOIN.', ['Start from the preserved table: customers.', 'LEFT JOIN matching orders; unmatched order columns become NULL.', 'Place date conditions in the join when unmatched customers must remain.', 'Use COUNT(order.id), not COUNT(*), when counting matched order rows.'], { prompt: 'Which clause placement preserves customers who have no recent order?', choices: ['WHERE orders.created_at >= cutoff', 'ON orders.customer_id = customers.id AND orders.created_at >= cutoff', 'INNER JOIN orders', 'HAVING orders.created_at >= cutoff before grouping'], answer: 1, rationale: 'A WHERE predicate on the nullable right table removes unmatched rows, effectively undoing the LEFT JOIN. Put the match condition in ON.' }, [{ prompt: 'Why is NULL not equal to NULL in SQL?', answer: 'NULL means unknown or missing, so equality cannot be evaluated as true; use IS NULL for the explicit check.' }, { prompt: 'What does an INNER JOIN discard?', answer: 'Rows that have no match on either side of the join condition.' }, { prompt: 'When is HAVING used?', answer: 'To filter groups after aggregation, unlike WHERE which filters rows before grouping.' }], ['Predict output for a LEFT JOIN with one unmatched customer.', 'Move a filter from WHERE to ON and explain the difference.', 'Write a query that counts customers with zero orders.', 'Add a NULL-safe condition.'], 'Join type describes what survives; predicate location decides whether your intended survivors are quietly removed.'),
  10: day('Use windows when you need calculations across related rows without collapsing the result set.', 'Leaderboard and salary bands', 'HR wants to show each employee, their department rank, and how their salary compares with the department average.', ['Partition rows by department so each calculation restarts in the right group.', 'Order within the partition for ranking.', 'Choose ROW_NUMBER for unique sequence, RANK for gaps after ties, or DENSE_RANK for no gaps.', 'Keep the employee row visible while adding aggregate information with OVER().'], { prompt: 'Which function gives tied salaries the same rank and leaves gaps after the tie?', choices: ['ROW_NUMBER()', 'RANK()', 'DENSE_RANK()', 'COUNT()'], answer: 1, rationale: 'RANK assigns equal rank to ties and then skips positions. DENSE_RANK also ties but does not leave gaps.' }, [{ prompt: 'What does PARTITION BY do?', answer: 'It creates independent groups for a window calculation while retaining individual rows.' }, { prompt: 'Why not GROUP BY for a per-employee rank?', answer: 'GROUP BY collapses rows; a window function adds the result alongside each original row.' }, { prompt: 'What makes an ordering deterministic?', answer: 'A complete ORDER BY, often including a stable tiebreaker such as an ID.' }], ['Rank sample salaries with all three rank functions.', 'Compute a department average beside each employee.', 'Add a deterministic tiebreaker.', 'Explain which rank is right for a prize allocation.'], 'Windows answer “how does this row compare with its peers?” while preserving the row you still need to inspect.'),
  11: day('Choose indexes from actual access patterns and verify them with the plan rather than intuition.', 'Slow order-history page', 'An orders table has ten million rows. The dashboard filters by customer_id and recent created_at, then sorts newest first.', ['Start with the exact WHERE, JOIN, and ORDER BY shape—not with a column list.', 'Estimate selectivity: a customer filter may reduce millions of rows to a small set.', 'Consider a composite index whose leading column matches the common equality filter.', 'Inspect EXPLAIN before and after; writes and storage are the trade-off.'], { prompt: 'What index is most plausibly useful for frequent customer history queries ordered by newest date?', choices: ['An index only on a low-cardinality status column', 'A composite index beginning with customer_id and then created_at', 'An index on every column', 'No index because the table is large'], answer: 1, rationale: 'The common equality filter narrows by customer first, then the date ordering can be served efficiently. Validate against the database plan and workload.' }, [{ prompt: 'What is selectivity?', answer: 'How strongly a predicate narrows a table; a highly selective condition matches relatively few rows.' }, { prompt: 'Why can indexes slow writes?', answer: 'Each insert, update, or delete may need to maintain additional ordered structures.' }, { prompt: 'What does EXPLAIN provide?', answer: 'The database’s intended execution strategy, such as scans, joins, estimated rows, and costs.' }], ['Write the dashboard query shape.', 'Propose and justify one index.', 'Read a plan for a full scan versus index lookup.', 'Name one workload where the index is not worth it.'], 'An index is a maintained promise about access order. It pays only when it matches a real, repeated query shape.'),
  12: day('Protect data changes with transaction boundaries, isolation choices, and reversible migrations.', 'Inventory reservation', 'Two buyers attempt to reserve the last item at the same time. A deployment also needs to add a NOT NULL field to a live table.', ['Define the invariant: available quantity must never become negative.', 'Perform check and update inside a transaction with an appropriate lock or atomic condition.', 'Understand isolation anomalies before choosing a level.', 'Use an expand–migrate–contract deployment so old and new application versions can coexist.'], { prompt: 'What is the safest database-level pattern for reserving one remaining item?', choices: ['Read quantity in the browser then update later', 'Atomically update only when quantity is greater than zero inside a transaction', 'Disable all constraints', 'Retry forever without checking state'], answer: 1, rationale: 'An atomic guarded update prevents two concurrent readers from both claiming the final item. Client-side reads are race-prone.' }, [{ prompt: 'What does atomicity mean?', answer: 'A transaction’s changes happen as one all-or-nothing unit.' }, { prompt: 'What is a deadlock?', answer: 'Transactions wait in a cycle for resources held by each other; one must be aborted or retried.' }, { prompt: 'Why expand before contract in migration?', answer: 'It preserves compatibility while old and new application versions overlap during deployment.' }], ['Trace two competing reservations.', 'Write an invariant next to the update.', 'Plan an additive migration and rollback.', 'Name the lock order that reduces a deadlock risk.'], 'Transactions protect invariants, while migration discipline protects production compatibility. They solve different kinds of failure.'),
  13: day('Diagnose database scenarios by separating correctness, schema design, and execution cost.', 'Checkout slowdown after growth', 'Checkout becomes slow after traffic doubles. Engineers debate adding a cache, an index, or rewriting a query that joins several tables.', ['Reproduce the path with representative parameters and data volume.', 'Inspect query timing and EXPLAIN before selecting a fix.', 'Check correctness first: duplicate joins or wrong isolation can look like performance problems.', 'Choose the smallest change that fixes the measured bottleneck and define a regression check.'], { prompt: 'What is the strongest first move when a once-fast query slows after data growth?', choices: ['Add a cache without measurement', 'Collect the execution plan and actual row/timing evidence', 'Drop foreign keys', 'Rewrite every query in the service'], answer: 1, rationale: 'The plan reveals whether the bottleneck is scans, cardinality estimates, join strategy, sorting, or something outside the database.' }, [{ prompt: 'Why can a join multiply rows unexpectedly?', answer: 'If the relationship is not one-to-one at the join level, each matching combination produces a row.' }, { prompt: 'What makes a migration safe?', answer: 'A tested forward path, compatibility window, observability, and a clear rollback or recovery plan.' }, { prompt: 'What should a performance fix include?', answer: 'A measurement baseline, the expected improvement, and a regression signal after release.' }], ['Turn a vague “slow” report into three measurable questions.', 'Name a query plan symptom and its possible fix.', 'Check a join for fan-out.', 'Write a rollback trigger.'], 'Performance work is evidence work. A good optimisation explains why it is needed and how you will know it worked.'),
  14: day('Switch deliberately between AI and technical modes during a mixed timed paper.', 'Technical section rehearsal', 'You face SQL, DBMS, pseudocode, OOP, and software-engineering questions after a demanding AI section.', ['Classify the question type before solving: output trace, schema rule, algorithm property, or engineering trade-off.', 'For code, trace state in a compact table instead of mentally rerunning the entire program.', 'For SQL, identify grain and row survival before calculating output.', 'Reserve final minutes for flagged questions and accidental blanks.'], { prompt: 'A pseudocode question has nested loops and an early break. What is the safest first action?', choices: ['Estimate Big-O from memory', 'Create a small trace table for the supplied input', 'Choose the longest answer', 'Convert it to recursion'], answer: 1, rationale: 'Output-prediction questions are safest when state changes are externalised. Complexity alone does not determine the printed value.' }, [{ prompt: 'What is a question’s “grain” in SQL?', answer: 'The real-world entity represented by one result row, such as one customer, order, or customer-month.' }, { prompt: 'Why flag rather than rush a hard item?', answer: 'It protects easy marks and gives you a later chance to resolve a real trade-off.' }, { prompt: 'What should a post-mock review contain?', answer: 'Concept gap, reasoning mistake, time issue, and the next concrete repair action.' }], ['Run 10 mixed technical questions on a timer.', 'Annotate each miss by failure type.', 'Redo two output traces without looking.', 'Choose one topic for targeted practice.'], 'Mixed tests reward rapid classification. Know what kind of thinking a stem demands before you begin it.'),
  15: day('Make program state visible so output and logic questions stop feeling like guessing.', 'Loop trace under pressure', 'A loop updates two indices, changes a running sum, and conditionally skips an element. The answer choices differ by one iteration.', ['Write initial values in columns before the loop begins.', 'For each iteration, evaluate conditions in execution order.', 'Record every mutation immediately, especially increments and assignments.', 'Stop only when the loop guard becomes false; do not infer intent from variable names.'], { prompt: 'What is the most reliable way to solve an output-trace question?', choices: ['Trust the variable name', 'Use a state table for each relevant iteration', 'Optimise the code first', 'Choose the answer with the most common value'], answer: 1, rationale: 'A compact trace externalises working memory and exposes off-by-one or branch behaviour.' }, [{ prompt: 'What is operator precedence?', answer: 'The defined order in which parts of an expression are evaluated unless parentheses make it explicit.' }, { prompt: 'Why is integer division a common trap?', answer: 'It discards the fractional part in integer types, so a value such as 5/2 may become 2.' }, { prompt: 'What does an invariant do?', answer: 'It states a property that remains true at a defined point in every iteration and helps reason about correctness.' }], ['Trace a loop with i, j, and sum columns.', 'Add parentheses to a confusing expression.', 'State one loop invariant.', 'Create one edge input that executes zero iterations.'], 'If you cannot point to the state after each step, you do not yet know the program’s output.'),
  16: day('Select an array or string pattern from constraints, then defend its invariant.', 'Longest stable user session', 'Given event IDs, find the longest contiguous segment with no repeated ID. The input can be large.', ['Recognise “contiguous” as a hint toward a window rather than a subsequence approach.', 'Keep a left boundary, right boundary, and last-seen index map.', 'When a duplicate appears inside the window, move left past its prior location.', 'State the invariant: the current window has unique IDs.'], { prompt: 'Which structure prevents rescanning the window when a duplicate event arrives?', choices: ['A nested loop over all prior elements', 'A map from value to last seen position', 'A recursive call for each event', 'A sorted copy only'], answer: 1, rationale: 'A last-seen map lets the left pointer jump directly, supporting linear-time traversal.' }, [{ prompt: 'What distinguishes two pointers from a sliding window?', answer: 'A sliding window is a two-pointer technique with a maintained contiguous-range invariant.' }, { prompt: 'When does hashing help?', answer: 'When fast membership, frequency, or last-position lookup is needed.' }, { prompt: 'What boundary case often breaks this pattern?', answer: 'Moving the left pointer backward when a duplicate was seen before the current window.' }], ['Write the unique-window invariant.', 'Trace a duplicate entering the window.', 'Test an empty array and all-equal values.', 'Explain time and space complexity.'], 'Patterns are compressed reasoning. Name the invariant before coding so you know which pointer is allowed to move and why.'),
  17: day('Choose an algorithm from structure and constraints, not from the topic you revised most recently.', 'Feature selection under a budget', 'You have candidate features with a benefit and a cost. Some choices are independent; other variants allow partial use or require all-or-nothing selection.', ['Ask whether local best choice can block a better global answer.', 'For greedy, identify an exchange argument or counterexample before trusting the rule.', 'For dynamic programming, define a state that contains exactly the history needed for future decisions.', 'Match complexity to constraints; a correct O(n²) plan may still time out.'], { prompt: 'What is the key proof obligation before using a greedy choice?', choices: ['That it uses a loop', 'That an optimal solution can be transformed to include the local choice without becoming worse', 'That the input is sorted', 'That recursion is avoided'], answer: 1, rationale: 'A greedy algorithm needs a correctness argument, often an exchange argument. Local attractiveness alone is insufficient.' }, [{ prompt: 'What does a DP state represent?', answer: 'A subproblem summarised so its answer can be reused when building larger answers.' }, { prompt: 'Why define base cases explicitly?', answer: 'They anchor the recurrence and describe the smallest problems whose answers are already known.' }, { prompt: 'What is a counterexample useful for?', answer: 'It quickly disproves a tempting strategy by showing one valid input where it fails.' }], ['Try to break a greedy rule with a tiny input.', 'Write state, transition, and base case for a DP.', 'Estimate operations for the maximum constraint.', 'Explain why your chosen approach fits.'], 'Algorithm choice is a claim about structure. Make the claim explicit enough that you can try to disprove it.'),
  18: day('Represent relationships with the data structure that makes the required operations natural.', 'Dependency graph for builds', 'A build system must compile prerequisites before dependents and detect a circular dependency.', ['Model tasks as vertices and dependency direction consistently.', 'Use indegree or DFS states to detect cycles.', 'Use a queue for breadth-first processing when prerequisites become ready.', 'Treat visited state as part of the algorithm, not a convenience.'], { prompt: 'What finding proves a directed dependency graph contains a cycle during topological processing?', choices: ['The queue starts empty', 'Fewer vertices are processed than exist', 'An edge has a weight', 'The graph is disconnected'], answer: 1, rationale: 'If a cycle remains, all vertices in it retain an incoming dependency and cannot be removed by topological processing.' }, [{ prompt: 'When is a stack useful?', answer: 'When the most recently added item must be processed first, as in undo, parsing, or DFS traversal.' }, { prompt: 'What does BFS naturally find in an unweighted graph?', answer: 'Shortest number of edges from a start node to each reachable node.' }, { prompt: 'Why track visited nodes?', answer: 'To avoid repeated work and infinite traversal in cyclic graphs.' }], ['Draw a four-task dependency graph.', 'Run a topological order by hand.', 'Create a cycle and observe the failure condition.', 'Compare queue versus stack traversal.'], 'The representation should make invalid states visible: cycles, duplicates, and unreachable nodes should emerge from the model.'),
  19: day('Explain OOP as controlled variation behind a stable contract, not as a vocabulary list.', 'Notification service redesign', 'Email, SMS, and push notifications share a send operation but have different validation and delivery logic.', ['Identify the stable behaviour clients need: send a message and receive a result.', 'Put shared intent behind an interface or abstract base.', 'Use polymorphism so callers depend on the contract rather than a chain of type checks.', 'Keep state private and expose only operations that preserve invariants.'], { prompt: 'Which design best avoids editing a large if/else chain each time a notification channel is added?', choices: ['One global variable for the current channel', 'A common notifier interface with channel-specific implementations', 'Copy the send function into every caller', 'Make all fields public'], answer: 1, rationale: 'A stable abstraction lets clients call the common operation while new channel implementations vary behind it.' }, [{ prompt: 'What is encapsulation?', answer: 'Bundling state with operations and restricting direct access so invariants are preserved.' }, { prompt: 'What is overriding?', answer: 'A derived type provides its own runtime implementation of an inherited virtual or interface operation.' }, { prompt: 'When is composition preferable to inheritance?', answer: 'When behaviour is assembled from independent capabilities rather than expressing a durable “is-a” relationship.' }], ['Sketch the notifier interface and two implementations.', 'Mark data that should stay private.', 'Show one polymorphic call site.', 'Explain a virtual dispatch result.'], 'Abstraction earns its place when it removes conditional complexity while making contracts clearer, not when it merely adds classes.'),
  20: day('Follow a request across the system and recognise where reliability, security, and delivery practices meet.', 'Checkout API incident', 'Customers see duplicate charges after a mobile network retry. The API deploy happened minutes earlier and logs are hard to correlate.', ['Trace browser or app → DNS → HTTPS → load balancer → API → database.', 'Recognise retries and timeouts as normal distributed-system behaviour.', 'Use idempotency keys so repeat requests do not repeat the side effect.', 'Connect logs, traces, deployment version, and request ID before blaming a single layer.'], { prompt: 'What protects a payment endpoint from charging twice when a client retries after a timeout?', choices: ['A larger response body', 'An idempotency key stored with the resulting operation', 'Turning off HTTPS', 'A client-side sleep only'], answer: 1, rationale: 'An idempotency key allows the server to recognise a repeated logical request and return the existing result instead of repeating the charge.' }, [{ prompt: 'Why is HTTPS relevant beyond encryption?', answer: 'It also provides integrity and authenticates the server through certificates in normal browser use.' }, { prompt: 'What does CI provide?', answer: 'Automated integration checks that give quick evidence a change can be safely combined.' }, { prompt: 'Why correlate by request ID?', answer: 'It ties events across services and layers into one user-visible operation.' }], ['Trace a request in six hops.', 'Define an idempotency key contract.', 'Write a log line with correlation fields.', 'Name one rollback signal after deployment.'], 'Production failures cross boundaries. The fastest diagnosis keeps the operation connected across those boundaries.'),
  21: day('Use tests and observability to make a change safe before a user discovers the regression.', 'Browser-specific checkout failure', 'Checkout works in Chrome but fails in Safari after a date parsing change. A generated test only checks that a button exists.', ['Reproduce the failure at the smallest meaningful layer.', 'Write a test that asserts the user outcome, not merely the presence of UI.', 'Separate unit, integration, and end-to-end responsibilities.', 'Add diagnostics that explain which input, browser, version, and response caused failure.'], { prompt: 'Which test is most valuable for a browser-specific payment-date regression?', choices: ['A snapshot of the page title', 'A cross-browser flow that enters the date and verifies the accepted checkout outcome', 'A test that imports the component only', 'A manual note saying Safari is different'], answer: 1, rationale: 'The regression is a user flow and browser compatibility issue, so the test must exercise that input and the resulting behaviour in the affected environment.' }, [{ prompt: 'What is regression testing?', answer: 'Testing that previously working behaviour remains correct after a change.' }, { prompt: 'Why are logs insufficient alone?', answer: 'Logs describe events; metrics and traces help quantify, correlate, and locate behaviour across a system.' }, { prompt: 'What is a test oracle?', answer: 'The source of truth used to decide whether an observed result is correct.' }], ['Turn the incident into a failing test.', 'Choose the right test layer.', 'Add three diagnostic fields.', 'Describe the smallest safe fix.'], 'A test is valuable when it guards the actual risk. A green check that never exercises the failure is theatre.'),
  22: day('Debug by making a falsifiable hypothesis and shrinking the failing input.', 'Frequency counter returns the wrong winner', 'A function should return the most frequent value, but fails when counts tie and when the array is empty.', ['Read the contract before the implementation: define tie rule and empty-input behaviour.', 'Use the smallest counterexample that fails.', 'Track state transitions with a trace rather than patching the first suspicious line.', 'Add tests for boundaries, repeated values, and ties after fixing the root cause.'], { prompt: 'What is the best first artefact after discovering an incorrect output?', choices: ['A larger random input', 'A minimal reproducible input paired with expected and actual values', 'A rewrite in another language', 'A comment saying “fix later”'], answer: 1, rationale: 'A minimal counterexample reduces noise, exposes the violated condition, and becomes a permanent regression test.' }, [{ prompt: 'What is an off-by-one error?', answer: 'A boundary is included or excluded one iteration too early or too late.' }, { prompt: 'Why test empty input?', answer: 'It exposes assumptions about initial values, indexing, and the existence of a first element.' }, { prompt: 'What is root cause analysis?', answer: 'Finding the underlying condition that produced the defect rather than masking its visible symptom.' }], ['Write the function contract.', 'Create three boundary tests.', 'Trace variables on the smallest failing input.', 'Explain why the final patch fixes the cause.'], 'Debugging is controlled experiment design: make the failure small, state the expected invariant, and test one explanation at a time.'),
  23: day('Recognise defects that hide behind correct-looking code: circular arithmetic, overflow, pointer movement, and recurrence.', 'Clockwise dial movement', 'Positions 1 through N form a circle. The code computes the distance between successive targets but undercounts wrap-around moves.', ['Translate the narrative into a mathematical position model.', 'Check direct distance and wrap distance separately when movement is constrained.', 'Update the current position after every target; stale state can make later answers wrong.', 'Use a wide enough integer type before multiplying or accumulating.'], { prompt: 'With clockwise-only movement on 1..N, what must a distance calculation account for?', choices: ['Only absolute difference', 'Wrap-around from a higher current position to a lower target', 'Sorting all targets first', 'Binary search in the dial'], answer: 1, rationale: 'A lower target may be reached only by completing the remaining arc through N and back to 1. Absolute difference ignores the direction constraint.' }, [{ prompt: 'What is integer overflow?', answer: 'A value exceeds the representable range of its type, causing wraparound or undefined/incorrect behaviour depending on language and operation.' }, { prompt: 'Why can an apparently valid recurrence fail?', answer: 'Its base case, transition, state meaning, or evaluation order may not match the problem.' }, { prompt: 'What makes a pointer bug subtle?', answer: 'The pointer often remains in bounds while silently skipping or reprocessing data.' }], ['Draw a five-position circle and trace wrap-around.', 'Choose a type for a large sum.', 'Test the smallest and largest valid inputs.', 'Write one invariant for moving pointers.'], 'Hard bugs often live at the boundary between a story and its formal model. Rebuild that model before editing code.'),
  24: day('Prompt an AI coding assistant like a reviewer-ready engineering brief, then verify every claim.', 'Constrained array task', 'You need a C++ solution for a large input, but a vague request produces O(n²) code and misses duplicate handling.', ['State the task, inputs, outputs, constraints, language, and required complexity.', 'Ask for a short approach before code so assumptions are visible.', 'Request named edge cases and a complexity explanation.', 'Independently trace the code; AI output is a proposal, not a proof.'], { prompt: 'Which detail most directly prevents an AI assistant from choosing an algorithm too slow for the input?', choices: ['A request for “clean code” only', 'Explicit input constraints and target complexity', 'A higher token budget alone', 'A friendly greeting'], answer: 1, rationale: 'Constraints determine feasibility. They tell the assistant whether quadratic, linear, or logarithmic work is acceptable.' }, [{ prompt: 'What should a good coding prompt include?', answer: 'Problem goal, I/O, constraints, language, edge cases, expected complexity, and validation request.' }, { prompt: 'Why request an approach before code?', answer: 'It exposes an incorrect algorithm choice before you spend time inspecting implementation details.' }, { prompt: 'What must you verify after receiving code?', answer: 'Correctness on boundaries, complexity, language details, and whether it actually follows the stated contract.' }], ['Write a structured prompt for an array problem.', 'Ask for three edge tests.', 'Find one way an O(n²) approach could slip in.', 'Review the answer as if you owned production responsibility.'], 'The quality of AI assistance is bounded by the specificity of the brief and the rigour of the review.'),
  25: day('Spend a limited AI budget in stages: clarify, plan, implement, test, and repair.', 'Two-thousand-token coding simulation', 'You have a token-limited assistant and a problem with an ambiguous edge case. A single giant prompt risks wasting the entire budget on the wrong approach.', ['First ask concise clarifying questions or state assumptions.', 'Request a plan and complexity, then challenge it with a counterexample.', 'Ask for implementation only after the approach survives review.', 'Reserve budget for test failures and a final audit of edge cases.'], { prompt: 'What is the best use of the first assistant exchange under a tight token budget?', choices: ['Request a long full solution with no constraints', 'Confirm interpretation, constraints, and a concise approach', 'Ask it to explain every data structure ever made', 'Use all tokens on formatting'], answer: 1, rationale: 'Early clarification prevents the most expensive failure: implementing a solution to the wrong problem.' }, [{ prompt: 'Why keep a token reserve?', answer: 'Unexpected tests and defects require a repair loop; spending everything on a first draft eliminates that loop.' }, { prompt: 'What is a hidden-test mindset?', answer: 'Actively looking for valid but unusual inputs that violate an unstated assumption.' }, { prompt: 'When should you reject assistant code?', answer: 'When it fails the contract, cannot justify complexity, or has unverified assumptions—even if it looks polished.' }], ['Split 2,000 tokens across five stages.', 'Write one clarification question.', 'Make a counterexample for the proposed algorithm.', 'Record a final verification checklist.'], 'A limited assistant is most useful as a staged collaborator. Preserve your own reasoning and budget for the repair cycle.'),
  26: day('Communicate a precise conclusion under time pressure and recognise the rule behind a reasoning pattern.', 'Client incident update', 'A client asks why a service was delayed and what will happen next. Separately, you face a syllogism where wording tries to make an invalid conclusion feel natural.', ['Lead with observed fact, impact, action, and next update time.', 'Avoid causal claims that logs do not yet support.', 'For syllogisms, translate statements into sets before judging a conclusion.', 'For visual or grid tasks, isolate one transformation rule at a time.'], { prompt: 'Which incident update is strongest?', choices: ['“Everything is probably fine.”', '“We observed elevated checkout errors from 10:05–10:17; mitigation is active; next update at 10:30.”', '“The database definitely caused it” without evidence', 'A long chronology with no action'], answer: 1, rationale: 'It communicates observable status, impact window, action, and a commitment without inventing cause.' }, [{ prompt: 'Why separate observation from cause?', answer: 'An observation is evidence; a cause is a hypothesis that needs validation.' }, { prompt: 'What makes a syllogism conclusion valid?', answer: 'It follows from the set relationships in the premises, not from how plausible it sounds.' }, { prompt: 'What should you do with an unfamiliar cognitive-game instruction?', answer: 'Read the tutorial, identify scoring rule and transformations, then use simple trial cases before speeding up.' }], ['Write a four-sentence client update.', 'Draw a Venn diagram for a syllogism.', 'State one visual pattern rule.', 'Practice saying an uncertain conclusion professionally.'], 'Clear communication is disciplined reasoning made visible: say what you know, what you are doing, and what happens next.'),
  27: day('Tell coherent engineering stories that make your ownership, trade-offs, and learning visible.', 'Project walkthrough', 'An interviewer asks about your RAG or full-stack project. A generic feature list does not show how you made decisions or handled constraints.', ['Open with user problem and success measure.', 'Describe your architecture through data flow, not a list of buzzwords.', 'Choose one trade-off: latency versus quality, indexing cost versus freshness, or speed versus safety.', 'End with a failure, what evidence exposed it, and what you changed.'], { prompt: 'What makes a project explanation technically credible?', choices: ['Listing every library first', 'Linking a user problem, design choice, trade-off, validation, and outcome', 'Memorising a generic company slogan', 'Avoiding all failures'], answer: 1, rationale: 'Interviewers can evaluate reasoning when they hear why a design was chosen, how it was tested, and what you learned.' }, [{ prompt: 'What is a STAR story useful for?', answer: 'Structuring a behavioural answer around situation, task, action, and result without losing ownership.' }, { prompt: 'How should you discuss a failure?', answer: 'State the impact, evidence, correction, and prevention—not excuses or a claim that nothing went wrong.' }, { prompt: 'What does “individual contribution” mean?', answer: 'The specific decisions, code, experiments, or coordination you personally owned and can defend.' }], ['Outline a two-minute project story.', 'Draw a simple architecture.', 'Prepare one trade-off answer.', 'Rehearse one failure-and-recovery story.'], 'A strong interview answer gives the listener a model of how you think, not only a list of technologies you have seen.'),
  28: day('Run a full mock like a diagnostic simulation: pace, flag, review, and turn results into next actions.', 'Forty-question rehearsal', 'The mixed mock contains 20 AI and 20 technical questions. Your goal is to finish with enough time for real review, not to linger on the first hard scenario.', ['Set a first-pass time budget and protect it.', 'Answer clear items, flag constrained trade-offs, and note question type.', 'Use review time to compare surviving options against every stated constraint.', 'After submission, turn each miss into a lesson, rule, and scheduled retest.'], { prompt: 'What is the most useful signal from a mock score?', choices: ['A claim that you will definitely clear the assessment', 'The pattern of concept, reading, and pacing errors that determines the next study block', 'The colour of the score card', 'Whether every question felt familiar'], answer: 1, rationale: 'A mock is preparation evidence, not a selection prediction. Its value is the targeted action it enables.' }, [{ prompt: 'Why separate first pass and review?', answer: 'It protects straightforward marks while reserving time for questions where careful comparison can change the result.' }, { prompt: 'What should a mistake notebook store?', answer: 'The chosen answer, correct reasoning, missed cue, linked lesson, and retest date.' }, { prompt: 'What is a useful timing metric?', answer: 'Median or average time by question type, interpreted alongside accuracy rather than alone.' }], ['Take the full mock under a fixed timer.', 'Flag instead of freezing.', 'Review three misses in writing.', 'Schedule the two weakest concepts.'], 'A mock becomes useful only when it changes tomorrow’s study plan.'),
  29: day('Convert performance data into a focused repair plan rather than rereading everything.', 'Weak-topic recovery', 'Your recent attempts show weak SQL joins, medium RAG security, and strong array patterns. You have one study session before the final review.', ['Prioritise weak, high-frequency, prerequisite concepts.', 'Revisit the smallest lesson section that repairs the misconception.', 'Use retrieval and a fresh scenario, not passive rereading alone.', 'Stop when performance is stable enough and protect time for broader readiness.'], { prompt: 'What is the best response to 45% accuracy on joins but 90% accuracy on already-mastered arrays?', choices: ['Spend equal time on every topic', 'Repair joins with a short lesson revisit and fresh output-prediction scenarios', 'Ignore joins because they are unpleasant', 'Repeat only array questions'], answer: 1, rationale: 'Targeted revision uses evidence to repair the highest-value gap while avoiding over-practice of a mastered skill.' }, [{ prompt: 'What is spaced retesting?', answer: 'Returning to a concept after time has passed to check retention rather than only immediate familiarity.' }, { prompt: 'Why is passive rereading weak evidence?', answer: 'Recognition can feel fluent even when you cannot retrieve or apply the idea independently.' }, { prompt: 'What signals readiness improvement?', answer: 'Consistent correct application across fresh questions, not one lucky attempt.' }], ['Choose two gaps from your actual analytics.', 'Write a revision hypothesis for each.', 'Do one fresh scenario after revision.', 'Set a retest date.'], 'Revision should be surgical: evidence chooses the target, retrieval checks the repair, and fresh context confirms transfer.'),
  30: day('Leave with a calm, evidence-based readiness routine and an interview-ready explanation toolkit.', 'Final readiness review', 'The night before assessment, new rumours appear online. You have a final mock result, a mistake queue, and a set of project stories.', ['Trust official campus instructions over reports or speculation.', 'Use a short final review of personal error rules, not a new topic binge.', 'Prepare logistics, rest, and a time-management routine.', 'Keep project explanations and question-asking ready for the next interview stage.'], { prompt: 'What is the strongest final-night preparation choice?', choices: ['Start several advanced topics from scratch', 'Review personal error rules, logistics, and a small confidence-building set', 'Search indefinitely for leaked questions', 'Ignore sleep because more hours always help'], answer: 1, rationale: 'A final review should consolidate reliable patterns and reduce execution risk. Unverified material and panic cramming increase noise.' }, [{ prompt: 'What should outrank candidate reports?', answer: 'Current official instructions from your campus or employer communication.' }, { prompt: 'What is a readiness review?', answer: 'A realistic summary of strengths, remaining gaps, routine, and next actions—not a guarantee of any outcome.' }, { prompt: 'What should you carry into an interview?', answer: 'Clear project stories, honest trade-offs, questions for the interviewer, and the ability to reason aloud.' }], ['Write your exam-day timeline.', 'Read the five most useful rules from your notebook.', 'Practice one project explanation aloud.', 'Stop at a planned time and rest.'], 'Readiness is controlled execution: know your next action, respect evidence, and leave enough energy to use what you learned.')
};
